import{_ as e,o as s,c as t,a4 as l}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"goroutine GMP 模型","description":"","frontmatter":{},"headers":[],"relativePath":"os/sched/gmp.md","filePath":"os/sched/gmp.md","lastUpdated":1788475713000}'),n={name:"os/sched/gmp.md"};function o(r,a,i,p,c,d){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="goroutine-gmp-模型" tabindex="-1">goroutine GMP 模型 <a class="header-anchor" href="#goroutine-gmp-模型" aria-label="Permalink to &quot;goroutine GMP 模型&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>Go runtime 的核心创新不是语法 / 多线程抽象 / GC 而是它的调度器 <code>GMP</code> (Goroutine / Machine / Processor). 它把用户态 goroutine + OS thread + 逻辑 P 三层抽象叠在一起, 让用户写 10 万个 goroutine 仍能在 64 核机器上 O(N_top) 不退化协力. 内核不感知有 goroutine, 它只看到一个进程跑很少几条 OS 线程. 而这层抽象实现背后是同一个抽象一直在反复出现: thread local + work stealing + central 稀释 — DSA &quot;lock-free work queue + ring buffer&quot; 的工程化.</p><h2 id="_1-g-m-p-各自什么" tabindex="-1">1. G / M / P 各自什么 <a class="header-anchor" href="#_1-g-m-p-各自什么" aria-label="Permalink to &quot;1. G / M / P 各自什么&quot;">​</a></h2><ul><li><strong>G</strong> (Goroutine): 一个用户态 task. 大小仅 8 KB 栈可起步, 不绑死固定 OS thread.</li><li><strong>P</strong> (Processor): 一个逻辑 &quot;执行权&quot;. 全局 <code>GOMAXPROCS</code> 个 (默认 = ncpu). 每个 P 有自己的本地 runqueue 装 G. 实际上 P 是一个虚拟资源&quot;票据&quot;.</li><li><strong>M</strong> (Machine): 一个真 OS 线程. M 必须 attach 到某个 P 才能跑对应的 G.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌─ P0 local runq: [G1, G2, G3]\\</span></span>
<span class="line"><span>                  ├─ P1 local runq: [G4, G5]     |  ┐</span></span>
<span class="line"><span>GOMAXPROCS=4  →   ├─ P2 local runq: [G6]         |  ├ M0..M_k = OS threads attached</span></span>
<span class="line"><span>                  └─ P3 local runq: [G7, G8, G9] ┘   </span></span>
<span class="line"><span>                  </span></span>
<span class="line"><span>                  global runq: (overflowed goroutines)</span></span>
<span class="line"><span>                  netpoller: (waiting-on-IO goroutines)</span></span></code></pre></div><p>任何时刻, 多个 M 上各自的核上跑 G. 不需要 G 在核心之间迁移, 也少 lock 争.</p><h2 id="_2-work-stealing-关键性能技巧" tabindex="-1">2. work stealing: 关键性能技巧 <a class="header-anchor" href="#_2-work-stealing-关键性能技巧" aria-label="Permalink to &quot;2. work stealing: 关键性能技巧&quot;">​</a></h2><p>P 的 local queue 空了想拿新 G ⇒ 它会:</p><ol><li>尝试自己 P 的 local queue;</li><li>work steal — 从别的 P 的 queue 里 steali 一半;</li><li>拿 global runqueue;</li><li>拿 netpoller ready 任务.</li></ol><p>work stealing 的算法详 + Go runtime 自内调度器 = 论文 Anderson et al. 2010 之类的 <em>work-stealing deques</em>. 高级实现加 chase / pop / steal 各有 lock-free 实现 (e.g. treiber stack with bounded queue 加 bins).</p><p><strong>实测 work stealing 关键收益</strong>: 在 GOMAXPROCS=Ncpu 下, G uniform 分配到 P 上, cross-P queue 大致 O(no lock) ⇒ N 个 P 一齐 100 个并发任务.</p><h2 id="_3-g-的状态机-接管-syscall" tabindex="-1">3. G 的状态机: 接管 syscall <a class="header-anchor" href="#_3-g-的状态机-接管-syscall" aria-label="Permalink to &quot;3. G 的状态机: 接管 syscall&quot;">​</a></h2><p>一般 user code 在 goroutine 上跑:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>G: runnable → running → syscall → blocked</span></span>
<span class="line"><span>   ↑                       ↓</span></span>
<span class="line"><span>   └───── 调度重新分配 ──────┘</span></span></code></pre></div><p>&quot;M1 正在跑 G1, G1 syscall 阻塞&quot;, runtime 会:</p><ol><li>把 M1 我想 briefly detach (在 lock, FS syscall, ...)</li><li>当 P0 引 syscall block too long: 想办法抢 P0 给另一个 M</li><li>新 M2 接管 P0, 继续从 local runq 拿新 G 跑</li></ol><p><strong>实际效果</strong>: 你的 Go 服务在 Lua-like IO syscall 时 ( 1 ms, 10 ms ) 都不会因 syscall 阻塞丢 CPU 调度. 这是 KB 模式 (大约 = nginx work 共享 NGINX/GPU 由于 共享阻塞).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M0 + P0 + G1 — syscall 阻塞 → 此 M0 与 P0 的解绑</span></span>
<span class="line"><span>                                   ↓</span></span>
<span class="line"><span>P0 配新 M1 继续跑 G_x (本地 queue 中下个工)</span></span>
<span class="line"><span>M0 等 syscall 完成 ⇒ G1 重新 runnable 进 global runq or P0 local</span></span></code></pre></div><h2 id="_4-network-poller-epoll-直接接管" tabindex="-1">4. network poller: epoll 直接接管 <a class="header-anchor" href="#_4-network-poller-epoll-直接接管" aria-label="Permalink to &quot;4. network poller: epoll 直接接管&quot;">​</a></h2><p>Go 5.x+ runtime 在 Linux socket IO 用 epoll + nonblock fd. 一个后台线程 (netpoller M) 长期 epoll_wait. 当 fd 可读就解析 fd-event 反查 G, 把它标 runnable.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>G1 想 socket.Read(fd)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>syscall nonblock + epoll_ctl(ADD fd)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>runtime park G1 with 当G1变 runnable callback</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Go runtime netpoller M定期 epoll_wait → 当 fdk可读就叫 G1 校 runnable</span></span></code></pre></div><p><em>epoll</em> in <code>_thread_run*</code> is device same shape Ever 用 epoll + java 或 nginx: 的 same. Go runtime 只是把是用户 user reverse-detect G <strong>multiple G + open-ended M</strong> 配上 independent 其实是<strong>脱 roll abstraction</strong>.</p><h2 id="_5-抛弃-blocked-m-和-g-的-soft-timer" tabindex="-1">5. 抛弃 blocked M 和 G 的 soft timer <a class="header-anchor" href="#_5-抛弃-blocked-m-和-g-的-soft-timer" aria-label="Permalink to &quot;5. 抛弃 blocked M 和 G 的 soft timer&quot;">​</a></h2><p>一个 M 阻塞 syscall 太久 (e.g. &gt; 10-20 ms) ⇒ retassined P 给别的 M. 这个 handoff 的特殊性是 <strong>handoff 不再杀 M</strong> — 让 M 继续 run syscall完成 G1 ⇒ 在 syscall tail G 想重attach 到任何 P.</p><p>但 What if Go runtime 完全用 OS sysc copy 或 block too long (比如 &gt; 10 ms syscall)? <strong>SYS 要求 ca (sysmon) 起出现 ⇒ P handoff</strong>.</p><p>这个 abstraction 与 Linux smpaffinity 跨 node migration 同构: <strong>apps (及)kernel times prefer core local handoff 在考虑 cache locality</strong>.</p><h2 id="_6-实测-cfs-调度延迟-output" tabindex="-1">6. 实测: CFS / 调度延迟 / output <a class="header-anchor" href="#_6-实测-cfs-调度延迟-output" aria-label="Permalink to &quot;6. 实测: CFS / 调度延迟 / output&quot;">​</a></h2><p>在 default GOMAXPROCS=Ncpu:</p><ul><li>黄报 goroutine create 1 个 ~ 1 μs / 8 KB stack;</li><li>thread create 1 个 ~ 30 μs / 1-2 MB stack;</li><li>sysmon monitor syscall block + steal 抢 ~ 10-20 μs.</li></ul><p>goroutine 比 thread 更轻 → 高并发场景可 trivial 高 günstig manager concurrency size.</p><h2 id="_7-多语言对照" tabindex="-1">7. 多语言对照 <a class="header-anchor" href="#_7-多语言对照" aria-label="Permalink to &quot;7. 多语言对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言 runtime</th><th>协程调度器</th><th>配置</th></tr></thead><tbody><tr><td>Rust tokio</td><td>multi-thread runtime + work steal</td><td><code>#tokio::main(worker_threads=N)</code> 默认 CPU 数</td></tr><tr><td>Java Project Loom</td><td>virtual thread + FFI scheduler</td><td><code>Executors.newVirtualThreadPerTaskExecutor()</code></td></tr><tr><td>Erlang BEAM</td><td>preempt scheduler, priorities</td><td>也可以多个 per CPU</td></tr><tr><td>Python asyncio</td><td>单线程 cooperative scheduler</td><td><code>asyncio.run_until_complete()</code></td></tr><tr><td>Kotlin coroutines</td><td>更 dispatcher 由 runtimes</td><td><code>Dispatchers.IO/Default</code></td></tr></tbody></table><p>抽象叠出: <strong>goroutine scheduler is actually a user-level thread scheduler</strong>. 它 work stealing + per-P local queue + syscall 抢救 + epoll netpoller 是工程核心 learning.</p><h2 id="_8-这一章带走的东西" tabindex="-1">8. 这一章带走的东西 <a class="header-anchor" href="#_8-这一章带走的东西" aria-label="Permalink to &quot;8. 这一章带走的东西&quot;">​</a></h2><ul><li>G: 用户态 task; P: 执行票据; M: OS thread; 三层分离配上 caching/调度;</li><li>work stealing 拿到线性扩展 (DSA lock-free deque 实例);</li><li>syscall haoffee 阻塞 P 抢等 handoff 不仅 mask 与 opt code, 避 full 愚服务;</li><li>netpoller = epoll 实际 scheduling= async IO 用于附 internal;</li><li>抽象同构造 (tokio, java virtual threads 也有同 abstract):</li></ul>`,36)])])}const g=e(n,[["render",o]]);export{h as __pageData,g as default};
